class Solution {
  public int maximumLength(int[] nums, int k) {
    int[][] dp = new int[k][k];
    boolean[] seen = new boolean[k];
    int answer = 1;
    for (int value : nums) {
      int r = value % k;
      for (int p = 0; p < k; p++) {
        int q = (p + r) % k;
        if (!seen[p]) continue;
        int candidate = dp[p][q] == 0 ? 2 : dp[p][q] + 1;
        if (candidate > dp[r][q]) dp[r][q] = candidate;
        answer = Math.max(answer, dp[r][q]);
      }
      seen[r] = true;
    }
    return answer;
  }
}
